import{c as t,Q as r,j as o,m as a}from"./chunks/framework.W-g_WCNV.js";const u=JSON.parse('{"title":"TOTP security","description":"TOTP implementation details, clock skew handling, secret encryption, and recovery codes.","frontmatter":{"title":"TOTP security","description":"TOTP implementation details, clock skew handling, secret encryption, and recovery codes."},"headers":[],"relativePath":"security/totp-security.md","filePath":"security/totp-security.md"}'),i={name:"security/totp-security.md"};function s(n,e,c,d,l,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h2 id="totp-standard" tabindex="-1">TOTP standard <a class="header-anchor" href="#totp-standard" aria-label="Permalink to &quot;TOTP standard&quot;">​</a></h2><p>GateKeeper implements TOTP according to RFC 6238 with these parameters:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Value</th><th>Why</th></tr></thead><tbody><tr><td>Algorithm</td><td>SHA1</td><td>Required for compatibility with Google Authenticator and most apps</td></tr><tr><td>Digits</td><td>6</td><td>Standard for TOTP</td></tr><tr><td>Period</td><td>30 seconds</td><td>Standard for TOTP</td></tr></tbody></table><h2 id="clock-skew" tabindex="-1">Clock skew <a class="header-anchor" href="#clock-skew" aria-label="Permalink to &quot;Clock skew&quot;">​</a></h2><p>TOTP codes are derived from the current time, so if the server clock and the user&#39;s device clock differ, a valid code might fail. GateKeeper accepts the code from the current 30-second window and the previous window, giving a tolerance of up to 30 seconds of clock skew.</p><h2 id="secret-encryption" tabindex="-1">Secret encryption <a class="header-anchor" href="#secret-encryption" aria-label="Permalink to &quot;Secret encryption&quot;">​</a></h2><p>TOTP secrets are sensitive - anyone who obtains a secret can generate valid codes indefinitely without the physical device. GateKeeper encrypts every TOTP secret with <strong>AES-256-GCM</strong> before storing it in the database.</p><p>How it works:</p><ol><li>A 32-byte AES key is derived from <code>SECRET_KEY</code> using SHA-256. This means the actual key is always 256 bits regardless of how long <code>SECRET_KEY</code> is.</li><li>A random 12-byte nonce is generated for each encryption using <code>crypto/rand</code>.</li><li>The secret is encrypted with AES-GCM. Because GCM is an authenticated encryption mode, any tampering with the stored ciphertext is detected on decryption.</li><li>The nonce is prepended to the ciphertext, base64-encoded, and stored with a <code>v2:</code> version prefix.</li></ol><p><strong>Upgrading from older versions.</strong> If you ran GateKeeper before v0.4.0, existing TOTP secrets were stored with a simpler XOR-based scheme. They are automatically re-encrypted with AES-256-GCM the first time each user successfully logs in with their TOTP code. No manual migration step is needed.</p><p><strong>If SECRET_KEY is compromised.</strong> Rotate <code>SECRET_KEY</code> immediately and revoke all sessions. Users who enrolled TOTP with the old key will need to re-enroll, because their encrypted secrets in the database cannot be decrypted with the new key.</p><h2 id="brute-force-protection" tabindex="-1">Brute-force protection <a class="header-anchor" href="#brute-force-protection" aria-label="Permalink to &quot;Brute-force protection&quot;">​</a></h2><p>After 5 failed TOTP attempts within 10 minutes, the account is locked for 10 minutes. This matches the OTP lockout behavior.</p><h2 id="recovery-codes" tabindex="-1">Recovery codes <a class="header-anchor" href="#recovery-codes" aria-label="Permalink to &quot;Recovery codes&quot;">​</a></h2><p>Recovery codes are 10-character alphanumeric strings formatted as groups separated by hyphens (for example, <code>aB-3x-Qz-7m-Kp</code>). They are generated using <code>crypto/rand</code>.</p><p>Each code is stored as an individual argon2id hash. This means:</p><ul><li>The codes cannot be recovered from the database, even by an admin.</li><li>Verifying a recovery code requires checking each stored hash until one matches - this is intentionally slow to prevent brute-force.</li><li>Once a code is used, it is permanently marked as consumed and cannot be reused.</li></ul><p>8 codes are generated per enrollment. The count of unused codes is visible to admins.</p>',18)])])}const m=t(i,[["render",s]]);export{u as __pageData,m as default};
